```javascript
// test/login.spec.js
describe('Manual Login Test', function() {
  let loginCredentials;

  before(() => {
    // Load environment variables for login credentials
    loginCredentials = require('./environment');
  });

  it('should handle manual login', function() {
    cy.visit('/login');
    cy.get('input[type="email"]').type(loginCredentials.email);
    cy.get('input[type="password"]').type(loginCredentials.password);
    cy.get('button[type="submit"]').click();
    cy.contains('Login successful').should('exist');
  });
});

// test/dashboard.spec.js
describe('Dashboard Functionality Test', function() {
  it('should access dashboard after login', function() {
    cy.visit('/dashboard');
    cy.contains('Dashboard').should('exist');
  });
});

// environment.js
// This file contains the login credentials in an environment variable format
// You should not expose these in the public codebase
const environment = {
  email: 'user@example.com',
  password: 'securepassword123'
};

module.exports = environment;
```

**Security Considerations:**
- The login credentials are stored in a separate file (`environment.js`) and not exposed in the public codebase.
- The credentials are not hardcoded in the test files, and are instead loaded dynamically using `require('./environment')`.
- The test framework is modular, with separate test files for login and dashboard functionality, ensuring separation of concerns.

