const { login, navigateToDashboard } = require('./utils');

// Environment configuration
const config = {
  username: process.env.LOGIN_USERNAME,
  password: process.env.LOGIN_PASSWORD,
  dashboardUrl: process.env.DASHBOARD_URL
};

// Utility functions
function login() {
  cy.visit('/login');
  cy.get('#username').type(config.username);
  cy.get('#password').type(config.password);
  cy.get('#login-button').click();
}

function navigateToDashboard() {
  cy.visit(config.dashboardUrl);
}

// Test suite
describe('Manual Login and Dashboard Access', () => {
  beforeEach(() => {
    // Reset any state before each test
    cy.resetApp();
  });

  it('should allow manual login', () => {
    login();
    cy.url().should('include', '/dashboard');
  });

  it('should allow access to dashboard functionality', () => {
    navigateToDashboard();
    cy.get('.dashboard-title').should('be.visible');
  });
});

